// VERIFY: 0f5d7c71 manual
// OFFSET: 0x005210D0
void CGGameUI::CastItemSpell(WOWGUID guid, int32_t confirmed) {
    CGItem_C* item = static_cast<CGItem_C*>(ClntObjMgrObjectPtr(guid, TYPE_ITEM, __FILE__, __LINE__));

    if (!item) {
        return;
    }

    SpellRec spell;
    PendingSpellCast* cast = Spell_C_GetTargetingSpellCast();

    if (!cast || !g_spellDB.GetRecord(cast->m_data.m_spellId, &spell)) {
        return;
    }

    for (uint32_t i = 0; i < 3; i++) {
        int32_t effect = spell.m_effect[i];

        if (effect == SPELL_EFFECT_ENCHANT_ITEM || effect == SPELL_EFFECT_ENCHANT_ITEM_TEMPORARY || effect == SPELL_EFFECT_ENCHANT_ITEM_PRISMATIC) {
            if (item->GetItemStaticFlags(0) & ITEM_FLAG_PETITION) {
                return;
            }

            bool matchesSubclass = false;

            if (spell.m_effectMiscValueB[i]) {
                const ItemSubClassRec* subclass = SDBItemSubclassGetSubClassRec(7, spell.m_effectMiscValueB[i]);

                if (subclass && subclass->m_subClassID == static_cast<int32_t>(item->GetSubtypeID()) && subclass->m_classID == static_cast<int32_t>(item->GetClassID())) {
                    matchesSubclass = true;
                }
            }

            if (spell.m_equippedItemSubclass && (spell.m_equippedItemClass != static_cast<int32_t>(item->GetClassID()) || !((1 << item->GetSubtypeID()) & spell.m_equippedItemSubclass)) && !matchesSubclass) {
                Spell_C_SpellFailed(cast, &spell, 12, -1, -1, 0);
                return;
            }

            if (spell.m_equippedItemInvTypes && !((1 << item->GetInventoryType()) & spell.m_equippedItemInvTypes) && !matchesSubclass) {
                Spell_C_SpellFailed(cast, &spell, 12, -1, -1, 0);
                return;
            }

            SpellItemEnchantmentRec* enchant = g_spellItemEnchantmentDB.GetRecord(spell.m_effectMiscValue[i]);

            if (enchant && (enchant->m_flags & 1) && !item->IsBound() && !confirmed && item->GetInventoryType()) {
                CGGameUI::m_lastItemSpellTarget = item->m_obj->m_guid;
                FrameScript_SignalEvent(SCRIPT_EVENT_BIND_ENCHANT, nullptr);
                return;
            }

            CGItem_C::ItemPurchaseData* purchase = item->m_itemPurchaseData;

            if (purchase && spell.m_effect[i] != SPELL_EFFECT_ENCHANT_ITEM_TEMPORARY && !confirmed && static_cast<int32_t>(purchase->m_refundTimeLeft - ClntObjMgrGetActivePlayerObj()->GetPlayedTime() + 7200) > 0) {
                CGGameUI::m_lastItemSpellTarget = item->m_obj->m_guid;
                FrameScript_SignalEvent(SCRIPT_EVENT_END_REFUND, "%d", 1);
                return;
            }

            if (item->IsBound() && !item->IsBoundForTrade() && !confirmed) {
                SpellItemEnchantmentRec* boundEnchant;

                if (spell.m_effect[i] != SPELL_EFFECT_ENCHANT_ITEM_TEMPORARY || ((boundEnchant = g_spellItemEnchantmentDB.GetRecord(spell.m_effectMiscValue[i])) && (boundEnchant->m_flags & 1))) {
                    CGGameUI::m_lastItemSpellTarget = item->m_obj->m_guid;
                    FrameScript_SignalEvent(SCRIPT_EVENT_END_BOUND_TRADEABLE, "%s", "itemenchant");
                    return;
                }
            }

            if (enchant && item->GetEnchantmentSpell(0) && !item->HasOnUseEnchant()) {
                for (uint32_t j = 0; j < 3; j++) {
                    if (enchant->m_effect[j] == 7 && enchant->m_effectArg[j]) {
                        Spell_C_SpellFailed(cast, &spell, 170, -1, -1, 0);
                        return;
                    }
                }
            }

            uint32_t slot = spell.m_effect[i] != SPELL_EFFECT_ENCHANT_ITEM;

            if (!(item->GetItemStaticFlags(0) & ITEM_FLAG_PETITION)) {
                int32_t existingId = item->m_item->m_itemFieldEnchantment[slot].m_id;

                if (existingId) {
                    SpellItemEnchantmentRec* existing = g_spellItemEnchantmentDB.GetRecord(existingId);

                    if (existing && enchant) {
                        CGGameUI::m_lastItemSpellTarget = item->m_obj->m_guid;
                        FrameScript_SignalEvent(SCRIPT_EVENT_REPLACE_ENCHANT, "%s%s", existing->m_name, enchant->m_name);
                        return;
                    }

                    continue;
                }
            }
        }

        effect = spell.m_effect[i];

        if (effect != SPELL_EFFECT_PROSPECTING && effect != SPELL_EFFECT_MILLING) {
            continue;
        }

        if (effect == SPELL_EFFECT_PROSPECTING && !(item->GetItemStaticFlags(0) & 0x40000)) {
            Spell_C_SpellFailed(cast, &spell, 17, -1, -1, 0);
            return;
        }

        if (spell.m_effect[i] == SPELL_EFFECT_MILLING && !(item->GetItemStaticFlags(0) & 0x20000000)) {
            Spell_C_SpellFailed(cast, &spell, 16, -1, -1, 0);
            return;
        }

        WOWGUID none = { 0 };
        ItemStats_C* stats = g_itemDBCache.GetRecord(item->m_obj->m_entryID, none, nullptr, nullptr, false);

        if (stats) {
            CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();
            int32_t skillIndex = player->GetSkillIndex(stats->m_requiredSkill);

            if (skillIndex < 0 || static_cast<int32_t>(player->GetSkillValue(skillIndex)) < static_cast<int32_t>(stats->m_requiredSkillRank)) {
                Spell_C_SpellFailed(cast, &spell, 150, stats->m_requiredSkill, stats->m_requiredSkillRank, 0);
                return;
            }
        }

        int32_t minPoints;
        int32_t maxPoints;
        Spell_C_GetMinMaxPoints(&spell, i, &minPoints, &maxPoints, 0, 0, 0, 0);

        if (item->m_item->m_itemFieldStackCount < minPoints) {
            Spell_C_SpellFailed(cast, &spell, 55, item->m_obj->m_entryID, minPoints, 0);
            return;
        }
    }

    Spell_C_HandleSpriteClick(item, nullptr);
}

struct ClosestObjectMatchData {
    /* 0000 */ uint32_t m_typeMask;
    /* 0004 */ int32_t m_targetType;
    /* 0008 */ const char* m_name;
    /* 000C */ int32_t m_nameLength;
    /* 0010 */ bool m_hasRealm;
    /* 0014 */ CGUnit_C* m_unit;
    /* 0018 */ WOWGUID m_bestGuid;
    /* 0020 */ float m_bestDistance;
    /* 0024 */ int32_t m_ignoreHostileTotems;
};

// VERIFY: 337f01f7 auto
// OFFSET: 0x005130D0
static int32_t FilterClosestMatchCandidate(int32_t targetType, const WOWGUID& guid, CGUnit_C* unit) {
    switch (targetType) {
        case 1:
        case 2:
            return 0;

        case 4: {
            uint32_t high = static_cast<uint32_t>(guid.m_guid >> 32);

            if ((high & 0xF0000000) || !((high & 0xF07FFFFF) | static_cast<uint32_t>(guid.m_guid))) {
                return 0;
            }
        }

        case 3:
            return guid != unit->m_obj->m_guid && CGGameUI::IsRaidMemberOrPet(guid) ? 1 : 0;

        case 5:
            if (guid == unit->m_obj->m_guid) {
                return 0;
            }

            return CGPartyInfo::IsMember(guid) ? 1 : 0;

        case 6:
            return guid != unit->m_obj->m_guid && CGGameUI::IsPartyMember(guid) ? 1 : 0;

        default:
            return 1;
    }
}

// VERIFY: 3d3d6230 auto
// OFFSET: 0x00513190
static void UpdateClosestMatch(ClosestObjectMatchData* data, const WOWGUID& guid, const char* name, float distance) {
    if (data->m_bestDistance > distance && name && !SStrCmpUTF8I(name, data->m_name, data->m_nameLength)) {
        data->m_bestGuid = guid;
        data->m_bestDistance = distance;
    }
}

// VERIFY: f9e800e6 manual
// OFFSET: 0x0051FFE0
static int32_t ClosestObjectMatchProc(WOWGUID guid, void* param) {
    ClosestObjectMatchData* data = static_cast<ClosestObjectMatchData*>(param);
    CGObject_C* object = ClntObjMgrObjectPtr(guid, TYPE_OBJECT, __FILE__, __LINE__);

    if (!object) {
        return 1;
    }

    if (!(object->m_obj->m_type & data->m_typeMask)) {
        return 1;
    }

    if ((object->m_obj->m_type & TYPE_UNIT) && !UnitMatchesTargetType(data->m_unit, static_cast<CGUnit_C*>(object), data->m_targetType)) {
        return 1;
    }

    float distance = data->m_unit->GetDistanceToPos(object->GetPosition());

    if (guid == data->m_unit->m_obj->m_guid) {
        distance = 2500000000.0f;
    } else if (object->m_obj->m_type & TYPE_UNIT) {
        CGUnit_C* unit = static_cast<CGUnit_C*>(object);
        CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();

        if (data->m_ignoreHostileTotems && unit->GetCreatureType() == 11 && !player->IsFriendly(unit)) {
            return 1;
        }

        if (unit->IsDeadOrGhost() || (unit->m_unit->m_unitDynamicFlags & 0x20) || unit->GetClientStandState() == UNIT_DEAD) {
            distance = s_maxMatchDistance + distance;
        }
    }

    char fullName[305];
    const char* name;

    if (data->m_hasRealm && (object->m_obj->m_type & TYPE_UNIT)) {
        const char* realm = nullptr;
        name = static_cast<CGUnit_C*>(object)->GetUnitName(&realm, 1);

        if (realm) {
            SStrPrintf(fullName, sizeof(fullName), "%s-%s", name, realm);
            name = fullName;
        }
    } else {
        name = object->GetObjectName();
    }

    UpdateClosestMatch(data, object->m_obj->m_guid, name, distance);
    return 1;
}

// VERIFY: 3d96dbfb manual
// OFFSET: 0x00520190
WOWGUID CGGameUI::ClosestObjectMatch(const char* name, uint32_t typeMask, int32_t targetType, int32_t exact, float maxDistance, int32_t ignoreHostileTotems) {
    CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();

    if (!player) {
        return WOWGUID();
    }

    CGUnit_C* unit = player->GetPossessedUnit();

    if (!unit) {
        unit = player;
    }

    WOWGUID guid = WOWGUID();

    if (Script_GetGUIDFromToken(name, guid, true) && guid.m_guid != 0xFFFFFFFFFFFFFFFEULL) {
        if (!guid) {
            return WOWGUID();
        }

        CGObject_C* object = ClntObjMgrObjectPtr(guid, TYPE_OBJECT, __FILE__, __LINE__);

        if (object && !(typeMask & object->m_obj->m_type)) {
            return WOWGUID();
        }

        if (typeMask != TYPE_UNIT && typeMask != TYPE_PLAYER) {
            return guid;
        }

        if (object) {
            return UnitMatchesTargetType(unit, static_cast<CGUnit_C*>(object), targetType) ? guid : WOWGUID();
        }

        return FilterClosestMatchCandidate(targetType, guid, unit) ? guid : WOWGUID();
    }

    ClosestObjectMatchData data;
    data.m_typeMask = typeMask;
    data.m_targetType = targetType;
    data.m_name = name;
    data.m_nameLength = exact ? STORM_MAX_STR : SStrLenUTF8(name);
    data.m_hasRealm = SStrChr(name, '-') != nullptr;
    data.m_unit = unit;
    data.m_bestGuid = WOWGUID();
    data.m_bestDistance = maxDistance;
    data.m_ignoreHostileTotems = ignoreHostileTotems;

    if (targetType != 1 && targetType != 2) {
        for (uint32_t i = 0; i < 4; i++) {
            WOWGUID member = GetPartyMemberGUID(i);

            if (member && !ClntObjMgrObjectPtr(member, TYPE_UNIT, __FILE__, __LINE__)) {
                WOWGUID none = WOWGUID();
                NameCache* record = g_nameDBCache.GetRecord(member.m_guid, none, nullptr, nullptr, false);

                if (record) {
                    UpdateClosestMatch(&data, member, record->m_name, 2500000000.0f);
                }
            }
        }

        if (targetType != 5) {
            for (uint32_t i = 0; i < CGRaidInfo::m_numMembers; i++) {
                WOWGUID member = CGRaidInfo::m_members[i]->m_guid;

                if (member && !ClntObjMgrObjectPtr(member, TYPE_UNIT, __FILE__, __LINE__)) {
                    WOWGUID none = WOWGUID();
                    NameCache* record = g_nameDBCache.GetRecord(member.m_guid, none, nullptr, nullptr, false);

                    if (record) {
                        UpdateClosestMatch(&data, member, record->m_name, 2500000000.0f);
                    }
                }
            }
        }
    }

    ClntObjMgrEnumVisibleObjects(ClosestObjectMatchProc, &data);
    return data.m_bestGuid;
}

// VERIFY: 6fb7fcd5 auto
// OFFSET: 0x005131D0
static int QSortCompareNearestUnit(const void* a, const void* b) {
    const NearestUnitData* left = static_cast<const NearestUnitData*>(a);
    const NearestUnitData* right = static_cast<const NearestUnitData*>(b);

    if (!left || !right) {
        SErrDisplayAppFatalMessage("", "", 0);
    }

    if (left->m_inFront != right->m_inFront) {
        return 2 * (left->m_inFront == 0) - 1;
    }

    if (right->m_distanceSq == left->m_distanceSq) {
        return 0;
    }

    return right->m_distanceSq >= left->m_distanceSq ? -1 : 1;
}

// VERIFY: 7d0d99e3 manual
// OFFSET: 0x00518E40
int32_t UnitMatchesTargetType(CGUnit_C* unit, CGUnit_C* target, int32_t type) {
    switch (type) {
        case 1: {
            return unit->CanAttack(target) && !target->IsDeadOrGhost() && !(target->m_unit->m_unitDynamicFlags & 0x20) && target->GetClientStandState() != UNIT_DEAD;
        }

        case 2: {
            if (!(target->m_obj->m_type & TYPE_PLAYER)) {
                return 0;
            }

            return unit->CanAttack(target) && !target->IsDeadOrGhost() && !(target->m_unit->m_unitDynamicFlags & 0x20) && target->GetClientStandState() != UNIT_DEAD;
        }

        case 3: {
            return unit->CanAssist(target, false) && target->m_unit->m_unitFieldHealth > 0;
        }

        case 4: {
            if (!(target->m_obj->m_type & TYPE_PLAYER)) {
                return 0;
            }

            return unit->CanAssist(target, false) && target->m_unit->m_unitFieldHealth > 0;
        }

        case 5: {
            return CGPartyInfo::IsMember(target->m_obj->m_guid) ? 1 : 0;
        }

        case 6: {
            return CGGameUI::IsPartyMember(target->m_obj->m_guid) != 0;
        }

        default: {
            return 1;
        }
    }
}

// VERIFY: d9fd51cd manual
// OFFSET: 0x00524440
static int32_t TargetUpdateProc(WOWGUID guid, void* param) {
    CGUnit_C* searcher = static_cast<CGUnit_C*>(param);
    CGUnit_C* unit = static_cast<CGUnit_C*>(ClntObjMgrObjectPtr(guid, TYPE_UNIT, __FILE__, __LINE__));

    if (!unit || unit == searcher || !UnitMatchesTargetType(searcher, unit, s_nearestType)) {
        return 1;
    }

    C3Vector searcherPos = searcher->GetPosition();
    C3Vector unitPos = unit->GetPosition();
    float dx = unitPos.x - searcherPos.x;
    float dy = unitPos.y - searcherPos.y;
    float dz = unitPos.z - searcherPos.z;
    float distanceSq = dx * dx + dy * dy + dz * dz;
    C3Vector targetPos = unit->GetPosition();
    C3Vector fromPos = searcher->GetPosition();
    float facingTo = CalculateFacingTo(&fromPos, &targetPos);
    float delta = fmod(facingTo - searcher->GetFacing() + 12.566371f, 6.2831855f);
    static float s_coneAngle = 0.52359879f;
    int32_t inFront = 0;
    float maxDistanceSq;

    if (s_coneAngle > delta || 6.2831855f - s_coneAngle < delta) {
        maxDistanceSq = TARGET_NEAREST_FRONT_MAX_DISTANCE_SQUARED;
        inFront = 1;
    } else {
        maxDistanceSq = TARGET_NEAREST_BACK_MAX_DISTANCE_SQUARED;
    }

    if (maxDistanceSq >= distanceSq) {
        CreatureTypeRec* creatureType = g_creatureTypeDB.GetRecord(unit->GetCreatureType());

        if ((!creatureType || !(creatureType->m_flags & 1)) && World::QueryObjectVisible(unit->m_worldObject) && (!(unit->m_obj->m_type & TYPE_PLAYER) || !static_cast<CGPlayer_C*>(unit)->IsCommentatorUberOrInArena())) {
            NearestUnitData* data = s_nearestUnits.New();
            data->m_distanceSq = distanceSq;
            data->m_guid = guid;
            data->m_inFront = inFront;
        }
    }

    return 1;
}

// VERIFY: 72ff3550 manual
// OFFSET: 0x00524FC0
void TargetNearestEnemy(int32_t reverse, int32_t type) {
    while (true) {
        if (lua_tainted) {
            CGGameUI::ShowBlockedActionFeedback(nullptr, 0);
            return;
        }

        CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();

        if (!player) {
            return;
        }

        CGUnit_C* searcher = player->GetPossessedUnit();

        if (!searcher) {
            searcher = player;
        }

        uint32_t count;

        if (!s_nearestSortTime || !s_nearestTargetTime || s_nearestTargetTime + 3000 <= OsGetAsyncTimeMs() || !(count = s_nearestUnits.m_count) || s_nearestType != type) {
            s_nearestIndex = 0;
            s_nearestSortTime = 0;
            s_nearestTargetTime = 0;
            s_nearestType = type;
            s_nearestUnits.SetCount(0);
            ClntObjMgrEnumVisibleObjects(TargetUpdateProc, searcher);

            if (!s_nearestUnits.m_count) {
                if (player->GetTransportGUID() == searcher->m_obj->m_guid.m_guid) {
                    VehicleSeatRec* seat = player->m_vehiclePassenger ? player->m_vehiclePassenger->m_seatRec : nullptr;

                    if (seat && (seat->m_flags & 0x4000)) {
                        searcher = player;
                        ClntObjMgrEnumVisibleObjects(TargetUpdateProc, player);
                    }
                }

                if (!s_nearestUnits.m_count) {
                    return;
                }
            }

            qsort(s_nearestUnits.m_data, s_nearestUnits.m_count, sizeof(NearestUnitData), QSortCompareNearestUnit);
            s_nearestSortTime = OsGetAsyncTimeMs();

            if (!s_nearestSortTime) {
                s_nearestSortTime = 1;
            }

            count = s_nearestUnits.m_count;
        } else if (CGGameUI::m_lockedTarget == s_nearestUnits.m_data[s_nearestIndex].m_guid) {
            if (reverse) {
                if (s_nearestIndex) {
                    s_nearestIndex--;
                } else {
                    s_nearestIndex = s_nearestUnits.m_count - 1;
                }
            } else if (++s_nearestIndex >= s_nearestUnits.m_count) {
                s_nearestIndex = 0;

                if (s_nearestSortTime + 1000 <= OsGetAsyncTimeMs()) {
                    s_nearestSortTime = 0;
                    continue;
                }

                count = s_nearestUnits.m_count;
            }
        }

        if (!count) {
            return;
        }

        s_nearestTargetTime = OsGetAsyncTimeMs();
        uint32_t i = s_nearestIndex;
        CGUnit_C* unit = static_cast<CGUnit_C*>(ClntObjMgrObjectPtr(s_nearestUnits.m_data[i].m_guid, TYPE_UNIT, __FILE__, __LINE__));
        bool restart = false;

        while (true) {
            if (unit && UnitMatchesTargetType(searcher, unit, type)) {
                s_nearestIndex = i;
                CGGameUI::Target(s_nearestUnits.m_data[i].m_guid);
                return;
            }

            if (++i >= s_nearestUnits.m_count) {
                i = 0;

                if (s_nearestSortTime + 1000 <= OsGetAsyncTimeMs()) {
                    s_nearestSortTime = 0;
                    restart = true;
                    break;
                }
            }

            if (i == s_nearestIndex) {
                break;
            }

            unit = static_cast<CGUnit_C*>(ClntObjMgrObjectPtr(s_nearestUnits.m_data[i].m_guid, TYPE_UNIT, __FILE__, __LINE__));
        }

        if (restart) {
            continue;
        }

        s_nearestUnits.SetCount(0);
        return;
    }
}

