void CGGameUI::THREATMAP::AddUnit(const WOWGUID& guid) {
    WOWGUID* empty = nullptr;

    for (uint32_t i = this->m_units.Count(); i;) {
        i--;

        if (this->m_units[i] == guid) {
            return;
        }

        if (!this->m_units[i]) {
            empty = &this->m_units[i];
        }
    }

    if (!empty) {
        empty = this->m_units.New();
    }

    *empty = guid;
}

