// VERIFY: 4af1a050 manual
// OFFSET: 0x0051D7C0
void CGGameUI::StopCinematicInternal(void* param) {
    CGCamera* camera = CGWorldFrame::GetActiveCamera();
    FrameScript_SignalEvent(SCRIPT_EVENT_CINEMATIC_STOP, nullptr);
    CGObject_C* target = static_cast<CGObject_C*>(ClntObjMgrObjectPtr(camera->m_targetGUID, TYPE_OBJECT, __FILE__, __LINE__));

    if (target) {
        C3Vector position = target->GetPosition();
        float dz = camera->m_position.z - position.z;
        float dy = camera->m_position.y - position.y;
        float dx = camera->m_position.x - position.x;

        if (dx * dx + (dy * dy + dz * dz) > MAX_CAMERA_SHIFT_SQUARED) {
            World::Preload(target->GetPosition(), 0);
        }
    }

    camera->ClearModelCamera();
    CGObject_C::UpdateAllWorldObjects();
    ScrnLayerPaint();
    int32_t streaming = SFile::IsStreamingMode();

    if (!(SFile::IsTrial() | streaming)) {
        AsyncFileReadWaitAll();
    }

    SI2::StopSound(&CGGameUI::m_cinematic.m_music, 0, -1.0f, 1);
    CDataStore msg;
    msg.Put(static_cast<uint32_t>(CMSG_COMPLETE_CINEMATIC));
    msg.Finalize();
    ClientServices::Send2(&msg);
    CGGameUI::m_inCinematic = 0;
    DisableFadingScreen(0.25f, nullptr, nullptr);
    CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();

    if (player && !(player->m_unit->m_unitFieldFlags & 0x100000)) {
        CGChat::ZoneUpdate();
    }

    CGInputControl* input = CGInputControl::GetActive();
    input->m_mouseModeFlags &= ~0x40;
    input->UpdateMouseMode(0);
    CGInputControl::GetActive()->EnterWorld();
}

// VERIFY: 647caecd manual
// OFFSET: 0x0051F430
void CGGameUI::GetCorpsePosition(C3Vector& position) {
    if (!CGGameUI::m_corpseTransportGUID) {
        position = CGGameUI::m_corpsePos;
        return;
    }

    if (ClntObjMgrObjectPtr(CGGameUI::m_corpseTransportGUID, TYPE_OBJECT, __FILE__, __LINE__)) {
        C44Matrix transform;

        if (!MovementGetTransportMtxX(CGGameUI::m_corpseTransportGUID, &transform, ClntObjMgrGetActivePlayer(), __FILE__, __LINE__)) {
            position = CGGameUI::m_corpsePos;
            return;
        }

        position = CGGameUI::m_corpsePos * transform;
        s_corpseQueryTime = 0;
        return;
    }

    if (!s_corpseQueryTime || static_cast<int32_t>(time(nullptr) - s_corpseQueryTime) >= 0) {
        WDataStore msg;
        msg.Put(static_cast<uint32_t>(CMSG_CORPSE_MAP_POSITION_QUERY));
        msg.Put(static_cast<uint32_t>(CGGameUI::m_corpseTransportGUID.m_guid));
        msg.Finalize();
        ClientServices::Send2(&msg);
        s_corpseQueryTime = static_cast<int32_t>(time(nullptr)) + 30;
    }

    position = CGGameUI::m_corpsePos * s_corpseMapRotation;
}

// VERIFY: 8b0c9714 auto
// OFFSET: 0x00512C40
static void UpdateCorpseRange(int32_t inRange) {
    if (inRange == CGGameUI::m_corpseInRange) {
        return;
    }

    CGGameUI::m_corpseInRange = inRange;

    if (CGBattlefieldInfo::m_instanceType == 4) {
        return;
    }

    if (inRange) {
        FrameScript_SignalEvent(SCRIPT_EVENT_CORPSE_IN_RANGE + (CGGameUI::m_corpseMapID != CGGameUI::m_corpseActualMapID), nullptr);
    } else {
        FrameScript_SignalEvent(SCRIPT_EVENT_CORPSE_OUT_OF_RANGE, nullptr);
    }
}

// VERIFY: d4e934e0 manual
// OFFSET: 0x0051F5C0
void CGGameUI::UpdateCorpseDistance() {
    int32_t inRange = 0;

    if (CGGameUI::m_corpseMapID >= 0) {
        CGPlayer_C* player = static_cast<CGPlayer_C*>(ClntObjMgrObjectPtr(ClntObjMgrGetActivePlayer(), TYPE_PLAYER, __FILE__, __LINE__));

        if (player) {
            C3Vector corpse = { 0.0f, 0.0f, 0.0f };
            CGGameUI::GetCorpsePosition(corpse);

            if (CGGameUI::m_corpseMapID == CGPlayer_C::GetNewContinentID()) {
                MinimapSetCorpsePOI(corpse.x, corpse.y);
            }

            C3Vector position = player->GetPosition();
            float dx = position.x - corpse.x;
            float dy = position.y - corpse.y;
            float dz = position.z - corpse.z;

            if (dz * dz + dy * dy + dx * dx <= s_corpseRangeSq) {
                inRange = 1;
            }
        }
    }

    UpdateCorpseRange(inRange);
}

// VERIFY: 5e07095c manual
// OFFSET: 0x0051FDE0
void CGGameUI::UpdateInteractTarget() {
    if (!CGGameUI::m_interactTarget || CGGameUI::m_interactMaxDistSq <= 0.0f) {
        return;
    }

    bool clear = false;
    CGObject_C* object = ClntObjMgrObjectPtr(CGGameUI::m_interactTarget, TYPE_OBJECT, __FILE__, __LINE__);

    if (!object || (object->m_modelFlags & 0x10000)) {
        CGGameUI::ClearInteractTarget(CGGameUI::m_interactTarget, 0);
        return;
    }

    if (object->m_obj->m_type & TYPE_ITEM) {
        return;
    }

    CGPlayer_C* player = ClntObjMgrGetActivePlayerObj();

    if (!player) {
        CGGameUI::ClearInteractTarget(CGGameUI::m_interactTarget, 0);
        return;
    }

    uint32_t type = object->m_obj->m_type;

    if (type & TYPE_GAMEOBJECT) {
        CGGameObject_C* gameObject = static_cast<CGGameObject_C*>(object);

        if (!player->CGUnit_C::CanInteract(gameObject) || !gameObject->CheckRange()) {
            CGGameUI::ClearInteractTarget(CGGameUI::m_interactTarget, 0);
        }

        return;
    }

    if (type & TYPE_UNIT) {
        CGUnit_C* unit = static_cast<CGUnit_C*>(object);

        if (((type & TYPE_PLAYER) && player->m_obj->m_guid != object->m_obj->m_guid && !player->CanCooperate(unit)) || (!(object->m_obj->m_type & TYPE_PLAYER) && !player->CanInteract(unit))) {
            clear = true;
        }
    }

    if (player->GetDistanceToPos(object->GetPosition()) > CGGameUI::m_interactMaxDistSq || clear) {
        CGGameUI::ClearInteractTarget(CGGameUI::m_interactTarget, 0);
    }
}

